import {SUBSTEPS,DT,ACTION_DURATIONS} from './action-timing.js';
import {v,p,a,table,details} from './guide-markup.js';

export const GUIDE_TIME_TEXT={
 'guide-time-body':p(`Время мира измеряется в Т. Одна Т состоит из ${v(SUBSTEPS,'подшагов')}, поэтому тело и текущая деятельность меняются каждые ${v(DT,'Т')}. Скорость показа определяет, как быстро эти подшаги выполняются на компьютере; длительность действий внутри мира от неё не меняется.`)
 +p(`Действие — процесс с накопленным прогрессом. Начало движения ещё не переносит жителя в соседнюю клетку: перенос произойдёт при завершении. Пока процесс идёт, продолжается усвоение пищи и оплата деятельности. Малый контроллер может запросить пересмотр решения.`)
 +p(`Например, житель начинает движение в ${v(0,'Т')}. Если оно не прервётся, ${v(ACTION_DURATIONS[0],'подшагов')} спустя, в ${v(ACTION_DURATIONS[0]/SUBSTEPS,'Т')}, он окажется на соседнем гексе. Между этими моментами он остаётся на исходной клетке. Решение продолжить тот же процесс сохраняет прогресс, а запуск другого начинает новый отсчёт.`)
 +details('Точный порядок событий',
 p('Перед первым продвижением времени мир один раз подготавливает общий снимок деятельности и начальные решения жителей. Затем каждый подшаг проходит следующие фазы:')
 +'<ol><li>Счётчик подшага увеличивается. Обновляется автоматическая среда и наступившее восстановление пищи.</li><li>У всех жителей обновляются возраст, усвоение и расход энергии текущего процесса. Проверяется гибель. Процессы, достигшие своей длительности, попадают в очередь завершения.</li><li>Выполняются завершения. Сбор одной и той же пищи разрешается отдельно; при недостатке порций порядок собирающих перемешивается.</li><li>До новых решений прекращаются физически невозможные процессы и фиксируется общий снимок деятельности. Жители видят одну границу подшага.</li><li>Обновляются наблюдения и опыт. Без процесса вызывается основной мозг; при обычном незавершённом процессе малый контроллер решает, нужен ли пересмотр. Роды добровольно не пересматриваются.</li></ol>'
 +p('При завершении родов ребёнок создаётся на этой границе времени, но получает право принимать первое решение со следующего подшага. Завершение действия и следующее решение могут приходиться на одну границу: новый процесс ещё не получает за неё целый подшаг прогресса.')
 +table('Три разных счётчика',['Счётчик','Смысл'],[['Время мира','Число подшагов, делённое на '+v(SUBSTEPS)+'.'],['Возраст','Время от рождения конкретного жителя.'],['Прогресс процесса','Количество уже выполненных подшагов этого действия.']])
 +p('Параллельный расчёт сохраняет границы физических фаз и снимка наблюдений. Число Workers меняет организацию вычислений, а не единицу времени.'))
 +p(`Дальше: ${a('actions','действия и прерывания')}, ${a('food','усвоение пищи')}, ${a('selection','рождение потомка')}, ${a('world','управление запуском мира')}.`),
};
